  "implementation": "def solve(case):
    import json
    min_cluster_size = case['min_cluster_size']
    clusters = case['clusters']
    parent = case['parent']

    # Build data structures
    cluster_info = {}
    children = {}
    for c in clusters:
        cid = c['cluster_id']
        if not isinstance(cid, str):
            raise ValueError('cluster_id must be a string')
        size = c['size']
        if not isinstance(size, int):
            raise ValueError('size must be an integer')
        birth = c['birth_lambda']
        exits = c['point_exit_lambdas']
        if not isinstance(exits, list):
            raise ValueError('point_exit_lambdas must be a list')
        cluster_info[cid] = {
            'size': size,
            'birth_lambda': birth,
            'point_exit_lambdas': exits,
            'parent': parent.get(cid)
        }
        children[cid] = []
    # Build children lists
    for cid, par in parent.items():
        if par is not None:
            if par not in children:
                raise ValueError(f'Parent {par} not found')
            children[par].append(cid)
    # Validate all cluster_ids exist
    for cid in parent:
        if cid not in cluster_info:
            raise ValueError(f'cluster_id {cid} not in clusters')

    # Retained clusters: size >= min_cluster_size
    retained_ids = []
    stability = {}
    for cid, info in cluster_info.items():
        if info['size'] >= min_cluster_size:
            retained_ids.append(cid)
            s = sum(max(0, ex - info['birth_lambda']) for ex in info['point_exit_lambdas'])
            stability[cid] = s

    # Sort retained clusters by decreasing stability, then cluster_id ascending
    sorted_retained = sorted(retained_ids, key=lambda cid: (-stability[cid], cid))

    # Compute descendants for each cluster (full tree, including non-retained)
    desc_cache = {}
    def get_descendants(cid):
        if cid in desc_cache:
            return desc_cache[cid]
        res = set()
        for ch in children[cid]:
            res.add(ch)
            res.update(get_descendants(ch))
        desc_cache[cid] = res
        return res
    for cid in cluster_info:
        get_descendants(cid)

    # Selection
    selected = set()
    blocked = set()
    for cid in sorted_retained:
        if cid in blocked:
            continue
        if desc_cache[cid] & selected:
            continue
        selected.add(cid)
        # Block ancestors
        p = cluster_info[cid]['parent']
        while p is not None:
            blocked.add(p)
            p = cluster_info[p]['parent'] if p in cluster_info else None

    # Build output
    clusters_output = []
    for c in clusters:
        cid = c['cluster_id']
        if cluster_info[cid]['size'] >= min_cluster_size:
            clusters_output.append({
                'cluster_id': cid,
                'size': cluster_info[cid]['size'],
                'stability': stability[cid]
            })
    selected_sorted = sorted(selected)
    return {'clusters': clusters_output, 'selected_cluster_ids': selected_sorted}
